<script>
  import { randomString } from '@splendidlabz/utils/dom'
  import Tab from './Tab.svelte'
  import Tablist from './Tablist.svelte'
  import Tabpanels from './Tabpanels.svelte'
  const {
    tabs,
    id = randomString(),
    class: klass = '',
    activeIndex = 0,
    tablistClass = '',
    tabClass = '',
    tabpanelsClass = '',
    tablistOptions,
    tabOptions,
    tabpanelsOptions,
    children,
    ...rest
  } = $props()
</script>

<Tablist
  {...rest}
  class="{klass} {tablistClass}"
  target={id}
  {...tablistOptions}
>
  {#each tabs as tab, index (tab)}
    {@const { text, ...tabRest } = tab}
    <Tab
      class={tabClass}
      active={index === activeIndex}
      {...tabOptions}
      {...tabRest}
    >
      {text}
    </Tab>
  {/each}
</Tablist>

{#if children}
  <Tabpanels {id} class={tabpanelsClass} {...tabpanelsOptions}>
    {@render children()}
  </Tabpanels>
{/if}
